async (page) => {
const errors=[],checks=[];page.on('pageerror',e=>errors.push(e.message));const check=(ok,label)=>{if(!ok)throw Error(label);checks.push(label)};
await page.setViewportSize({width:1440,height:1000});await page.goto('http://127.0.0.1:5173/apprendre.html');await page.waitForTimeout(400);
await page.screenshot({path:'prototype/preview/apprendre-desktop.png'});
await page.locator('#check-answer').click();check(await page.locator('#answer-error').isVisible(),'Choix obligatoire et erreur accessible');
await page.locator('input[value="0"]').check();await page.locator('#check-answer').click();check((await page.locator('#feedback').textContent()).includes('25 %'),'Correction du pourcentage');check(await page.locator('#feedback li').count()===3,'Explication de chaque choix');
await page.locator('#retry-case').click();await page.locator('input[value="1"]').focus();await page.keyboard.press('Space');await page.locator('#check-answer').click();check((await page.locator('#feedback h3').textContent()).includes('bon réflexe'),'Bonne réponse au clavier');
await page.locator('#next-case').click();check((await page.locator('#case-title').textContent()).includes('référence'),'Cas suivant');await page.locator('input[value="2"]').check();await page.locator('#check-answer').click();check((await page.locator('#feedback h3').textContent()).includes('Vous avez'),'Correction source');
await page.locator('[data-case="2"]').click();await page.locator('input[value="1"]').check();await page.locator('#check-answer').click();check((await page.locator('#feedback h3').textContent()).includes('Vous avez'),'Correction script');await page.locator('#next-case').click();
await page.locator('.learn-rail a[href="#clinique"]').click();await page.waitForTimeout(700);check(await page.locator('.learn-rail a[href="#clinique"]').getAttribute('aria-current')==='location','Repère de section active');await page.screenshot({path:'prototype/preview/apprendre-clinique.png'});
await page.context().grantPermissions(['clipboard-read','clipboard-write']);await page.locator('#copy-prompt').click();await page.waitForFunction(()=>document.querySelector('#copy-prompt').textContent.includes('copié'));check((await page.locator('#copy-prompt').textContent()).includes('copié'),'Copie du prompt');await page.locator('.clinic-details summary').click();check(await page.locator('.clinic-details').getAttribute('open')!==null,'Détail de la clinique');
await page.locator('[data-creation="0"]').first().click();check(await page.locator('#creation-dialog').evaluate(d=>d.open),'Ouverture parcours');await page.locator('#copy-creation').click();await page.waitForFunction(()=>document.querySelector('#copy-creation').textContent.includes('copié'));check((await page.locator('#copy-creation').textContent()).includes('copié'),'Copie du prompt de création');await page.locator('#detail-notes').click();await page.locator('#note-text').fill('J’ai précisé les ombres et conservé le cadrage.');await page.locator('#notes-form button').click();check((await page.locator('#note-status').textContent()).includes('enregistrées'),'Enregistrement des notes');await page.keyboard.press('Escape');await page.reload();await page.locator('#open-notes').click();check((await page.locator('#note-text').inputValue()).includes('ombres'),'Notes conservées après rechargement');await page.keyboard.press('Escape');
await page.locator('#tweaks-open').click();for(const [name,value] of Object.entries({accent:'deep',density:'compact',layout:'stack',labels:'line',effects:'none',motion:'none'})){await page.locator(`#tweaks-form [name="${name}"]`).selectOption(value);check(await page.locator('body').getAttribute('data-'+name)===value,'Tweaks '+name);}await page.locator('#tweaks-form button[type="reset"]').click();await page.waitForTimeout(50);check(await page.locator('body').getAttribute('data-layout')==='columns','Réinitialisation Tweaks');await page.keyboard.press('Escape');check(await page.locator('#tweaks-open').evaluate(e=>e===document.activeElement),'Retour du focus après fermeture');
for(const width of [1440,1024,768,390,320]){await page.setViewportSize({width,height:900});await page.evaluate(()=>window.scrollTo(0,0));await page.waitForTimeout(400);check(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),'Pas de débordement '+width);if(width===390){await page.screenshot({path:'prototype/preview/apprendre-mobile.png'});await page.locator('.menu-toggle').click();check(await page.locator('#mobile-panel').isVisible(),'Menu mobile');await page.keyboard.press('Escape');check(!await page.locator('#mobile-panel').isVisible(),'Fermeture menu au clavier');}if(width===768)await page.screenshot({path:'prototype/preview/apprendre-tablet.png'});}
await page.setViewportSize({width:1440,height:1000});await page.emulateMedia({reducedMotion:'reduce'});check(await page.locator('.case-sheet').evaluate(e=>getComputedStyle(e).animationName)==='none','Préférence de réduction des animations');
for(let y=0;y<await page.evaluate(()=>document.body.scrollHeight);y+=650){await page.evaluate(y=>window.scrollTo(0,y),y);await page.waitForTimeout(80);}await page.evaluate(()=>window.scrollTo(0,0));await page.screenshot({path:'prototype/preview/apprendre-full.png',fullPage:true});check(await page.locator('img').evaluateAll(imgs=>imgs.every(i=>i.complete&&i.naturalWidth>0)),'Toutes les images chargées');check(errors.length===0,'Aucune erreur JavaScript');
return {checks,errors};
}

